import { registerSW as viteRegisterSW } from 'virtual:pwa-register';

/**
 * Registers the Workbox service worker generated by vite-plugin-pwa.
 * `registerType: 'autoUpdate'` means a new SW activates and reloads the page
 * automatically; we only log here. Safe to call in environments without SW
 * support (it no-ops).
 */
export function registerSW(): void {
  if (typeof window === 'undefined' || !('serviceWorker' in navigator)) {
    return;
  }

  viteRegisterSW({
    immediate: true,
    onOfflineReady() {
      console.info('[pwa] app ready to work offline');
    },
    onRegisteredSW(swUrl, registration) {
      console.info('[pwa] service worker registered', swUrl, registration?.scope);
    },
    onRegisterError(error) {
      console.error('[pwa] service worker registration failed', error);
    },
  });
}
